// Locate the TERMINAL ACTIONABLES BLOCK in an assistant turn (mt#4807).
//
// `communication-contract.mdc §The terminal actionables block` allows one marked
// terminal section to close a report, and forbids one thing inside it: *"never a
// Tier-0 decision (always `asks_create`)"*. Nothing enforced that, because
// nothing could FIND the block. This module is that half — a pure locator, with
// no opinion about what a unit means.
//
// **The contract's marker description does not match what agents write, and this
// module covers the measured forms rather than the described one.** The rule says
// *"(rule + heading)"*. A census of nine terminal actionables blocks in this
// project's transcripts over 2026-08-30 → 08-31 found roughly half of them
// carrying neither a rule nor a heading — an inline `**Terminal actionables:**`
// label opening a sentence. A locator keyed on the description alone would be
// blind to that half, and an agent that happened to use the inline form would be
// exempt from any downstream check by accident of formatting.
//
// Three forms are covered, and {@link ActionablesBlock.markerForm} reports which
// one matched so a consumer can measure them separately:
//
//   ---                                  heading      (observed 3/9)
//   ### Actionables
//   - merge PR #1
//
//   ---                                  bold-line    (observed 1/9)
//   **Actionables**
//   - merge PR #1
//
//   **Terminal actionables:** merge …    inline-label (observed 4/9)
//
// @see .minsky/hooks/ask-routing-deferral-detector.ts — the first consumer
// @see docs/architecture/adr-024-detection-mechanism-ladder-for-guidance-hooks.md
//      — Rung 1 prescribes the elision pass this module runs before matching

import { elideMarkdownNonProse } from "../../packages/domain/src/text/prose-elision";

/** Which of the three measured marker forms opened the block. */
export type ActionablesMarkerForm = "heading" | "bold-line" | "inline-label";

/**
 * One addressable item inside the block.
 *
 * For a list-shaped block this is a top-level bullet with its continuation
 * lines; for a prose-shaped one it is the whole body. `index` addresses the
 * ORIGINAL text, not the elided residual — see {@link locateActionablesBlock}.
 */
export interface ActionablesUnit {
  text: string;
  index: number;
}

export interface ActionablesBlock {
  markerForm: ActionablesMarkerForm;
  /** True when a thematic break (`---`, `***`, `___`) precedes the marker line. */
  precededByRule: boolean;
  /** Offset of the marker line into the ORIGINAL text. */
  markerIndex: number;
  units: ActionablesUnit[];
}

/**
 * The label text a marker must carry, in all three forms.
 *
 * `Terminal` is optional because both spellings are in the measured corpus and
 * they mean the same thing — the inline form tends to carry it, the headed forms
 * tend not to.
 */
const LABEL = String.raw`(?:terminal[ \t]+)?actionables`;

/** `### Actionables`, any heading level, optional trailing colon, alone on its line. */
const HEADING_RE = new RegExp(String.raw`^ {0,3}#{1,6}[ \t]+${LABEL}[ \t]*:?[ \t]*\r?$`, "gim");

/** `**Actionables**` alone on its line — a bold run standing in for a heading. */
const BOLD_LINE_RE = new RegExp(
  String.raw`^ {0,3}\*\*${LABEL}\*\*[ \t]*:?[ \t]*\r?$|^ {0,3}\*\*${LABEL}[ \t]*:\*\*[ \t]*\r?$`,
  "gim"
);

/**
 * `**Terminal actionables:** <prose>` — the label and its content on ONE line.
 *
 * Both colon placements occur (`**X:**` and `**X**:`), and a leading list bullet
 * is allowed because the label sometimes opens a bullet rather than a paragraph.
 * The lookahead requires content after the label: a bold label with nothing after
 * it is the `bold-line` form, and matching it here would take the wrong branch.
 */
const INLINE_LABEL_RE = new RegExp(
  String.raw`^ {0,3}(?:[-*+][ \t]+)?\*\*${LABEL}(?:[ \t]*:\*\*|\*\*[ \t]*:)[ \t]*(?=\S)`,
  "gim"
);

/**
 * A list item opener at ANY indent, capturing the indent.
 *
 * Indent is captured rather than bounded because depth is what separates a
 * top-level bullet from a sub-bullet, and CommonMark's 0-3 rule cannot make that
 * call: `  - child` sits inside 0-3 too. The splitter compares each item's indent
 * against the FIRST item's instead.
 */
const LIST_ITEM_RE = /^([ \t]*)[-*+][ \t]+\S/;

/**
 * Indent at which a non-list line still CONTINUES the preceding list item.
 *
 * CommonMark's continuation rule is content-column-relative; two spaces is the
 * shallowest indent any `- ` item can produce, so it is the safe floor. A line
 * shallower than this, after a list has started, ends the list — and with it the
 * block, which is what makes the terminal check mean anything.
 */
const CONTINUATION_INDENT = 2;

/** A thematic break, per CommonMark's three-or-more rule. */
const THEMATIC_BREAK_RE =
  /^ {0,3}(?:-[ \t]*){3,}$|^ {0,3}(?:\*[ \t]*){3,}$|^ {0,3}(?:_[ \t]*){3,}$/;

/** Anything that ENDS the block rather than continuing it. */
const BLOCK_TERMINATOR_RE = /^ {0,3}#{1,6}[ \t]/;

interface MarkerHit {
  form: ActionablesMarkerForm;
  /** Offset of the start of the marker LINE. */
  lineStart: number;
  /** Offset just past the marker itself — where the block body begins. */
  bodyStart: number;
}

/** The LAST marker of any form, or null. Ties break toward the later offset. */
function lastMarker(scanned: string): MarkerHit | null {
  const candidates: Array<[ActionablesMarkerForm, RegExp]> = [
    ["heading", HEADING_RE],
    ["bold-line", BOLD_LINE_RE],
    ["inline-label", INLINE_LABEL_RE],
  ];

  let best: MarkerHit | null = null;
  for (const [form, pattern] of candidates) {
    // Each RegExp is module-level and stateful under /g; reset before scanning.
    pattern.lastIndex = 0;
    let m: RegExpExecArray | null;
    while ((m = pattern.exec(scanned)) !== null) {
      const hit: MarkerHit = {
        form,
        lineStart: m.index,
        bodyStart: m.index + m[0].length,
      };
      if (best === null || hit.lineStart >= best.lineStart) best = hit;
      if (m.index === pattern.lastIndex) pattern.lastIndex += 1;
    }
  }
  return best;
}

/** True when the last non-blank line before `offset` is a thematic break. */
function hasPrecedingRule(scanned: string, offset: number): boolean {
  const before = scanned.slice(0, offset).split("\n");
  // The final element is the (empty) prefix of the marker line itself.
  for (let i = before.length - 2; i >= 0; i -= 1) {
    const line = before[i] ?? "";
    if (line.trim() === "") continue;
    return THEMATIC_BREAK_RE.test(line);
  }
  return false;
}

/**
 * Split a list-shaped body into top-level items, or return the whole body as one
 * unit when it carries no list.
 *
 * Offsets are relative to `bodyOffset`, which is an offset into the original.
 */
function splitUnits(body: string, bodyOffset: number): ActionablesUnit[] {
  const lines = body.split("\n");
  const units: ActionablesUnit[] = [];
  let cursor = 0;
  let current: { start: number; lines: string[] } | null = null;
  /** Indent of the first list item seen — the depth that counts as top level. */
  let baseIndent: number | null = null;

  const flush = (): void => {
    if (current === null) return;
    const text = current.lines.join("\n").trimEnd();
    if (text.trim() !== "") units.push({ text, index: bodyOffset + current.start });
    current = null;
  };

  for (const line of lines) {
    const lineStart = cursor;
    cursor += line.length + 1; // +1 for the newline `split` consumed

    if (BLOCK_TERMINATOR_RE.test(line) || THEMATIC_BREAK_RE.test(line)) break;

    const item = LIST_ITEM_RE.exec(line);
    if (item !== null) {
      const indent = (item[1] ?? "").length;
      if (baseIndent === null) baseIndent = indent;
      if (indent <= baseIndent) {
        flush();
        current = { start: lineStart, lines: [line] };
        continue;
      }
      // Deeper than the first item: a sub-bullet, which belongs to its parent.
      if (current !== null) {
        current.lines.push(line);
        continue;
      }
    }

    const isBlank = line.trim() === "";
    // A non-blank, under-indented line AFTER a list has started ends the list.
    // Without this the trailing prose of a non-terminal block is swallowed into
    // the last bullet, and the terminal check below passes vacuously.
    if (!isBlank && baseIndent !== null) {
      const indent = line.length - line.trimStart().length;
      if (indent < CONTINUATION_INDENT) break;
    }

    if (current !== null) {
      current.lines.push(line);
      continue;
    }
    // Leading blank lines between the marker and the body belong to neither the
    // marker nor the first unit — skip them, so a unit's offset addresses its
    // own first character.
    if (!isBlank) current = { start: lineStart, lines: [line] };
  }
  flush();

  return units;
}

/**
 * Split one unit into CLAUSES, newline-joined so a segmenting consumer scores each on its own.
 *
 * **Measured, and load-bearing (mt#4807).** An actionables bullet packs its act into a clause and
 * surrounds it with content. The originating instance is the clean case: *"**One yes needed before
 * PR 1:** a hashed JSON payload at a stable URL is a de facto dataset release of your editorial
 * layer (all-rights-reserved; the code is MIT). Smaller than the doc implies — the raw tweets are
 * already on the Community Archive's public API — but it should be a deliberate yes."* The act is
 * six words of ninety. Scored whole against decision exemplars it reads **0.3640** — below every
 * usable threshold. Scored by clause it reads **0.6747**.
 *
 * `splitCandidateSegments` (`packages/domain/src/detectors/embedding-nomination.ts`) splits on
 * `\n+` first and then on sentence terminators, so it cannot reach a clause inside a sentence —
 * and this corpus puts the act after a colon or between em-dashes about as often as it puts it in
 * a sentence of its own. Joining clauses with newlines hands that splitter one segment per clause
 * without changing it, which keeps every other detector that shares it untouched.
 *
 * Splits on sentence terminators, colons, semicolons, and spaced em/en dashes. Bold and backtick
 * marks are stripped: they are emphasis, and an embedding should not score `**` as content.
 * Fragments under 12 characters are dropped, matching the segmenter's own floor — a bare
 * `mt#4787` lead carries no act.
 */
export function splitUnitClauses(unit: string): string {
  const body = unit
    .replace(/^\s*[-*+]\s+/, "")
    .replace(/\*\*/g, "")
    .replace(/`/g, "");
  return body
    .split(/(?<=[.!?])\s+|\s*[:;]\s+|\s+—\s+|\s+–\s+/)
    .map((s) => s.trim())
    .filter((s) => s.length >= 12)
    .join("\n");
}

/**
 * Locate the terminal actionables block, or return null.
 *
 * **Matching runs on the ELIDED residual and slicing runs on the ORIGINAL.**
 * `elideMarkdownNonProse` is same-length by contract (ADR-024 Rung 1, amended
 * mt#4792), so an offset into one is a valid offset into the other. This is what
 * keeps a message that QUOTES an actionables block — inside a fence or a
 * blockquote, which is how the corpus discusses itself — from being read as
 * having one.
 *
 * **TERMINAL is enforced, not assumed.** The block must run to the end of the
 * message with only whitespace after it. That is what the contract's own wording
 * describes (a section that *closes* a report) and it is the load-bearing false-
 * positive guard: a mid-message "### Actionables" — a spec being discussed, a
 * rule being quoted in bare prose that elision does not reach — is not a report's
 * closing block and does not match.
 *
 * **Known residue, stated rather than designed away.** A message whose closing
 * block is followed by a sign-off sentence is missed by the terminal rule. No
 * instance of that shape appears in the measured census; if one shows up, it
 * belongs in the census before it belongs in this regex.
 */
export function locateActionablesBlock(text: string): ActionablesBlock | null {
  if (text.trim() === "") return null;

  const scanned = elideMarkdownNonProse(text);
  const marker = lastMarker(scanned);
  if (marker === null) return null;

  const body = scanned.slice(marker.bodyStart);
  const units = splitUnits(body, marker.bodyStart);
  if (units.length === 0) return null;

  // Terminal check: nothing but whitespace after the last unit. Measured on the
  // ELIDED text so a trailing fenced block counts as content, not as whitespace.
  const last = units[units.length - 1];
  if (last === undefined) return null;
  const afterLast = marker.bodyStart + (last.index - marker.bodyStart) + last.text.length;
  if (scanned.slice(afterLast).trim() !== "") return null;

  return {
    markerForm: marker.form,
    precededByRule: hasPrecedingRule(scanned, marker.lineStart),
    markerIndex: marker.lineStart,
    // Slice the ORIGINAL: a unit's text must be what the agent actually wrote,
    // not the elided residual, or a consumer would score blanked filler.
    units: units.map((u) => ({
      index: u.index,
      text: text.slice(u.index, u.index + u.text.length),
    })),
  };
}
